using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "FreezeEnemyAction", menuName = "Data/Battle/Battle Actions/Orion/Freeze Enemy Action")]
public class FreezeEnemyAction : StarRequirementAction
{
	[Header("Freeze Default Effect Action")]
	[SerializeField]
	private DefaultEffectAction freezeDefaultEffectAction;

	public override void CastTargetAmount(GameObject corruptedAnimal, int amount, GameObject source)
	{
		freezeDefaultEffectAction.CastTargetAmount(corruptedAnimal, amount, source);
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		freezeDefaultEffectAction.AreaCastTargetAmount(targets, amount, source);
	}
}
